    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    crosses = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 and all(
                0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 3
                for rr, cc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
            ):
                crosses.append((r, c, grid[r][c]))

    # Project colored crosses across their full row and column; vertical
    # projections take precedence at intersections. Hollow crosses erase
    # their row and column afterward. Original 3 arms remain visible.
    for r, c, color in crosses:
        if color != 0:
            for x in range(w):
                out[r][x] = color
    for r, c, color in crosses:
        if color != 0:
            for y in range(h):
                out[y][c] = color
    for r, c, color in crosses:
        if color == 0:
            for x in range(w):
                out[r][x] = 0
            for y in range(h):
                out[y][c] = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 3
    return out
